    vector<int> cheapest(101, INF);

    for (int i = 0; i < N; ++i) {
        int T, P;
        cin >> T >> P;
        cheapest[T] = min(cheapest[T], P);
    }

    vector<int> prices;
    for (int price : cheapest) {
        if (price != INF) prices.push_back(price);
    }

    sort(prices.begin(), prices.end());

    int count = 0;
    for (int price : prices) {
        if (R < price) break;
        R -= price;
        ++count;
    }

    cout << count << '\n';
    return 0;
